// Test Dart sort direction
void main() {
  // Test 1: numeric compareTo
  print("1.compareTo(2) = ${1.compareTo(2)}"); // Should be negative (ascending)
  print("2.compareTo(1) = ${2.compareTo(1)}"); // Should be positive

  // Test 2: string compareTo  
  print("'a'.compareTo('b') = ${'a'.compareTo('b')}"); // Should be negative
  print("'2'.compareTo('1') = ${'2'.compareTo('1')}"); // Should be positive (lexical)

  // Test 3: empty handling
  var dates = ['2026-09-10', '', '2026-09-15', '', '2026-09-05'];
  dates.sort((a, b) {
    final x = a, y = b;
    if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
    final nx = num.tryParse(x), ny = num.tryParse(y);
    final c = (nx != null && ny != null) ? nx.compareTo(ny) : x.compareTo(y);
    if (c != 0) return c;
    return 0;
  });
  print("Sorted dates: $dates"); // Should be [2026-09-05, 2026-09-10, 2026-09-15, '', '']
}
EOF
